CREATE TABLE IF NOT EXISTS ai_model_profiles(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE RESTRICT, name TEXT NOT NULL COLLATE NOCASE, model_id TEXT NOT NULL, capabilities_json TEXT NOT NULL DEFAULT '{}', openai_transport TEXT, enabled_for_chat INTEGER NOT NULL DEFAULT 0 CHECK(enabled_for_chat IN (0, 1)), capability_state TEXT NOT NULL DEFAULT 'unknown' CHECK(capability_state IN ('unknown', 'supported', 'unsupported')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(org_id, name));
CREATE INDEX IF NOT EXISTS ai_model_profiles_org ON ai_model_profiles(org_id, name);
CREATE TABLE IF NOT EXISTS ai_assignments(org_id TEXT NOT NULL REFERENCES organizations(id), assignment_key TEXT NOT NULL CHECK(assignment_key IN ('primary', 'summarization', 'tuning', 'image_generation', 'video_generation', 'chat_default')), profile_id TEXT NOT NULL REFERENCES ai_model_profiles(id) ON DELETE RESTRICT, updated_at TEXT NOT NULL, PRIMARY KEY(org_id, assignment_key));
CREATE TABLE IF NOT EXISTS ai_embedding_config(org_id TEXT NOT NULL REFERENCES organizations(id), connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE RESTRICT, model_id TEXT NOT NULL, dimensions INTEGER, updated_at TEXT NOT NULL, PRIMARY KEY(org_id));
CREATE TABLE IF NOT EXISTS ai_behavior(org_id TEXT NOT NULL REFERENCES organizations(id), default_system_prompt TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(org_id));
